import functools
import time


def retry(times, exceptions=(Exception,), delay=0.0, backoff=2.0, sleep=time.sleep):
    """Retry the decorated function on the given exceptions.

    The function is called at most ``times`` times. Between attempts it waits
    ``delay * backoff ** (attempt - 1)`` seconds via ``sleep``. The last
    exception is re-raised if every attempt fails.
    """
    if times < 1:
        raise ValueError(f"times must be at least 1, got {times}")
    if delay < 0:
        raise ValueError(f"delay must be non-negative, got {delay}")
    if backoff < 1:
        raise ValueError(f"backoff must be at least 1, got {backoff}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                attempt += 1
                wrapper.last_attempts = attempt
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt >= times:
                        raise
                    if delay:
                        sleep(delay * backoff ** (attempt - 1))

        wrapper.last_attempts = 0
        return wrapper

    return decorator

